urlset:
{% for page in site.pages %}

    {{ site.baseurl }}/{{ page.url }}
    {{ page.modified_at | date: "%Y-%m-%d" }}
    monthly
    0.5

{% endfor %}

{% for post in site.posts %}

    {{ site.baseurl }}/{{ post.url }}
    {{ post.modified_at | date: "%Y-%m-%d" }}
    monthly
    0.5

{% endfor %}
